def assert_response(responseBody, globalParam, statusCode, headers):
    if not isinstance(responseBody, dict):
        return False
    if statusCode != 200 or responseBody.get("code") != 0 or not responseBody.get("requestId"):
        return False
    page = responseBody.get("data")
    if not isinstance(page, dict) or not isinstance(page.get("items"), list):
        return False
    matches = [item for item in page["items"] if isinstance(item, dict) and item.get("topicId") == globalParam["T"]]
    return len(matches) == 1

def assert_response(responseBody, globalParam, statusCode, headers):
    if not isinstance(responseBody, dict):
        return False
    if statusCode != 200 or responseBody.get("code") != 0 or not responseBody.get("requestId"):
        return False
    data = responseBody.get("data")
    if not isinstance(data, dict):
        return False
    return data.get("topicId") == globalParam["T"] and data.get("status") == "accepted" and bool(data.get("roomId"))

def assert_response(responseBody, globalParam, statusCode, headers):
    if not isinstance(responseBody, dict):
        return False
    if statusCode != 400 or responseBody.get("code") != 40001:
        return False
    msg = responseBody.get("message")
    if isinstance(msg, str) and ("Traceback" in msg or "Exception" in msg):
        return False
    return True

